func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.data.Sizes[string(name)]; ok {
		return size
	}

	return t.fallback.Size(name)
}

// parseHexColor converts a hex color string (e.g., "#RRGGBB" or "#RRGGBBAA") to color.Color
func parseHexColor(hex string) (color.Color, error) {
	var r, g, b, a uint8 = 0, 0, 0, 255

	if len(hex) > 0 && hex[0] == '#' {
		hex = hex[1:]
	}

	if len(hex) == 6 {
		_, err := parseHexByte(hex, 0, &r)
		if err != nil {
			return nil, err
		}
		_, err = parseHexByte(hex, 2, &g)
		if err != nil {
			return nil, err
		}
		_, err = parseHexByte(hex, 4, &b)
		if err != nil {
			return nil, err
		}
	} else if len(hex) == 8 {
		_, err := parseHexByte(hex, 0, &r)
		if err != nil {
			return nil, err
		}
		_, err = parseHexByte(hex, 2, &g)
		if err != nil {
			return nil, err
		}
		_, err = parseHexByte(hex, 4, &b)
		if err != nil {
			return nil, err
		}
		_, err = parseHexByte(hex, 6, &a)
		if err != nil {
			return nil, err
		}
	} else {
		return nil, errors.New("invalid hex color format")
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexByte(hex string, offset int, out *uint8) (int, error) {
	val := uint8(0)
	for i := 0; i < 2; i++ {
		c := hex[offset+i]
		val <<= 4
		if c >= '0' && c <= '9' {
			val |= c - '0'
		} else if c >= 'a' && c <= 'f' {
			val |= c - 'a' + 10
		} else if c >= 'A' && c <= 'F' {
			val |= c - 'A' + 10
		} else {
			return 0, errors.New("invalid hex digit")
		}
	}
	*out = val
	return 2, nil
}

// loadFontResource loads a font file and returns it as a fyne.Resource
func loadFontResource(path string) fyne.Resource {
	data, err := os.ReadFile(path)
	if err != nil {
		fyne.LogError("Failed to load font", err)
		return nil
	}

	return fyne.NewStaticResource(path, data)
}

